  "Bem-vindo ao OMEGA DX10!": [
    "Welcome to OMEGA DX10!",
    "¡Bienvenido a OMEGA DX10!"
  ],
  "Olá, Tamer! Sua jornada pelo Mundo Digital começa agora. Aqui você receberá recompensas especiais do administrador. Boa sorte em suas batalhas!": [
    "Hello, Tamer! Your journey through the Digital World begins now. Here you will receive special rewards from the administrator. Good luck in your battles!",
    "¡Hola, Tamer! Tu viaje por el Mundo Digital comienza ahora. Aquí recibirás recompensas especiales del administrador. ¡Buena suerte en tus batallas!"
  ],
  "Presente de Nível 5 — Guilmon!": [
    "Level 5 Gift — Guilmon!",
    "¡Regalo de nivel 5 — Guilmon!"
  ],
  "Parabéns por atingir o Tamer Rank 5! Como recompensa especial, você recebe o Guilmon — um dinossauro do tipo Vírus com chamas poderosas e uma linha evolutiva incrível. Boa sorte nas batalhas!": [
    "Congratulations on reaching Tamer Rank 5! As a special reward, you receive Guilmon — a Virus-type dinosaur with powerful flames and an incredible evolution line. Good luck in battle!",
    "¡Felicidades por alcanzar el rango de Tamer 5! Como recompensa especial recibes a Guilmon, un dinosaurio de tipo Virus con poderosas llamas y una increíble línea evolutiva. ¡Buena suerte en las batallas!"
  ],
  "Presente de Nível 10 — Agumon (Saber)!": [
    "Level 10 Gift — Agumon (Saber)!",
    "¡Regalo de nivel 10 — Agumon (Saber)!"
  ],
  "Incrível, Tamer Rank 10! Você provou seu valor no Mundo Digital. Como reconhecimento especial, você recebe o Agumon (Saber) — a versão aprimorada do clássico Agumon do Tamer Masaru. Com seu tipo Vacina e golpes poderosos, ele será um parceiro formidável nas masmorras avançadas!": [
    "Amazing, Tamer Rank 10! You have proven your worth in the Digital World. As special recognition, you receive Agumon (Saber) — the enhanced version of Tamer Masaru's classic Agumon. With its Vaccine type and powerful attacks, it will be a formidable partner in advanced dungeons!",
    "¡Increíble, rango de Tamer 10! Has demostrado tu valor en el Mundo Digital. Como reconocimiento especial recibes a Agumon (Saber), la versión mejorada del clásico Agumon del Tamer Masaru. ¡Con su tipo Vacuna y poderosos ataques será un compañero formidable en las mazmorras avanzadas!"
  ],
  "Reforço Angelical — Pacote Especial!": [
    "Angelic Reinforcement — Special Pack!",
    "¡Refuerzo angelical — Paquete especial!"
  ],
  "Um pacote de reforço foi enviado para o seu Digivice! Você recebeu 1× Angemon, 1× Devimon e 20× Bateria Azul. Use as baterias para turbinar o nível dos seus Digimons na tela de status. Boa sorte, Tamer!": [
    "A reinforcement pack was sent to your Digivice! You received 1× Angemon, 1× Devimon and 20× Blue Battery. Use batteries to boost your Digimons' levels on the stats screen. Good luck, Tamer!",
    "¡Un paquete de refuerzo llegó a tu Digivice! Recibiste 1× Angemon, 1× Devimon y 20× batería azul. Usa las baterías para subir el nivel de tus Digimons en la pantalla de estadísticas. ¡Buena suerte, Tamer!"
  ],
  "🏠 Decoração Desbloqueada — Casa!": [
    "🏠 Decoration Unlocked — House!",
    "🏠 ¡Decoración desbloqueada — Casa!"
  ],
  "Parabéns por atingir o Tamer Rank 5! Você ganhou a Casa da DigiFarm. Acesse a aba \"Decoração\" na DigiFarm, toque na Casa e posicione-a onde quiser no campo. Ela é sólida — seus Digimons desviarão dela!": [
    "Congratulations on reaching Tamer Rank 5! You earned the DigiFarm House. Open the \"Decoration\" tab in DigiFarm, tap the House and place it anywhere on the field. It is solid — your Digimons will walk around it!",
    "¡Felicidades por alcanzar el rango de Tamer 5! Ganaste la casa de la DigiFarm. Abre la pestaña \"Decoración\", toca la casa y colócala donde quieras. ¡Es sólida y tus Digimons la rodearán!"
  ],
